def nav(file):
    groups=[('Collection',[('products.html','Explore the collection'),('black-drink.html','Black Drink'),('ionizers.html','Home water ionizers')]),('Our world',[('about.html','Our perspective'),('rituals.html','The journal'),('serving-guide.html','The serving notes')]),('Guides',[('benefits.html','Before you choose'),('reading-labels.html','Read your label'),('science.html','pH & product clarity'),('faq.html','Frequently asked')]),('For business',[('hospitality.html','Hospitality & events'),('partners.html','Trade & partnerships')])]
    features={
      'Collection':('products.html','lifestyle-v2/black-pour','Zubrex Black Drink and a clear glass','The current collection','For the table. For the home.'),
      'Our world':('rituals.html','lifestyle-v2/joyful-dining','Friends sharing Black Drink over a meal','The journal','Time at the table.'),
      'Guides':('benefits.html','campaign/ionizer-kitchen','Zubrex ionizer concept in a light kitchen','A practical guide','Before you choose.'),
      'For business':('hospitality.html','lifestyle-v2/hospitality','A waiter serving Black Drink in a restaurant','For hospitality & events','A place at your table.')}
    result='<ul id="site-menu">'
    for label,items in groups:
        href,img,alt,kicker,title=features[label]
        feature=f'<a class="nav-feature" href="{href}"><img src="assets/images/{img}-640.webp" alt="{alt}" width="640" height="427" loading="lazy"><span><small>{kicker}</small><strong>{title}</strong><span aria-hidden="true">↗</span></span></a>'
        result+='<li><details class="nav-dropdown"><summary '+('class="nav-current"' if file in [f for f,t in items] else '')+'>'+label+'<span aria-hidden="true">⌄</span></summary><div class="nav-panel"><div class="nav-panel-links"><p class="eyebrow">'+label+'</p>'+''.join(f'<a href="{f}" {"aria-current=page" if file==f else ""}>{t}<span aria-hidden="true">↗</span></a>' for f,t in items)+'</div>'+feature+'</div></details></li>'
    return result+f'<li><a class="mobile-contact" href="contact.html" {"aria-current=page" if file=="contact.html" else ""}>Contact & enquiries</a></li></ul>'

